<script type="text/javascript">
(function () {

  function findEcommerceItems() {
    try {
      if (!Array.isArray(window.dataLayer2)) return [];

      for (var i = window.dataLayer2.length - 1; i >= 0; i--) {
        var obj = window.dataLayer2[i];

        if (obj && Array.isArray(obj.ecommerce?.items)) {
          return obj.ecommerce.items;
        }
      }
      return [];
    } catch (e) {
      return [];
    }
  }

  function getMobonItemsFromDataLayer() {
    const items = findEcommerceItems();

    return items.map(item => ({
      productId: item.item_id || '',
      productName: item.item_name || '',
      productPrice: item.price != null ? Number(item.price) : '',
      productQty: item.quantity != null ? Number(item.quantity) : '',
      productCategory: item.item_category || ''
    }));
  }

  const mobonInterval = setInterval(() => {
    try {
      const items = findEcommerceItems();

      if (items.length > 0) {
        clearInterval(mobonInterval);

        window.DM_ITEMS = window.DM_ITEMS || {};
        window.DM_ITEMS.products = getMobonItemsFromDataLayer();
      }
    } catch (e) {
      // 에러 무시
    }
  }, 400);

